<?php
require_once __DIR__ . '/../config/db.php';
$pageTitle='Contracts | Freelance Marketplace System'; $successMsg=$_GET['success']??''; $errorMsg=$_GET['error']??''; $contracts=$conn->query("SELECT c.contract_id,c.start_date,c.end_date,c.status,c.proposal_id,p.bid_amount,p.project_id,p.freelancer_id,u.name AS freelancer_name,pr.title AS project_title FROM Contract c INNER JOIN Proposal p ON c.proposal_id=p.proposal_id INNER JOIN Freelancer f ON p.freelancer_id=f.freelancer_id INNER JOIN `User` u ON f.freelancer_id=u.user_id INNER JOIN Project pr ON p.project_id=pr.project_id ORDER BY c.contract_id"); include __DIR__ . '/../includes/header.php'; include __DIR__ . '/../includes/navbar.php';
?>
<section class="table-card"><div class="section-heading"><div><span class="eyebrow">Contract Records</span><h2 class="page-title">Contracts</h2><p class="page-intro">Contracts created from accepted proposals.</p></div><div class="section-actions"><a class="btn" href="<?php echo $basePath; ?>/pages/add_contract.php">+ Add Contract</a></div></div><?php if($successMsg!==''):?><div class="message success"><?php echo htmlspecialchars($successMsg); ?></div><?php endif;?><?php if($errorMsg!==''):?><div class="message error"><?php echo htmlspecialchars($errorMsg); ?></div><?php endif;?><div class="table-wrapper"><table><thead><tr><th>ID</th><th>Proposal ID</th><th>Freelancer</th><th>Project</th><th>Bid Amount</th><th>Start Date</th><th>End Date</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($contracts&&$contracts->num_rows>0): while($row=$contracts->fetch_assoc()):?><tr><td><?php echo $row['contract_id']; ?></td><td><?php echo $row['proposal_id']; ?></td><td><?php echo htmlspecialchars($row['freelancer_name']); ?> (ID: <?php echo $row['freelancer_id']; ?>)</td><td><?php echo htmlspecialchars($row['project_title']); ?> (ID: <?php echo $row['project_id']; ?>)</td><td>$<?php echo number_format((float)$row['bid_amount'],2); ?></td><td><?php echo htmlspecialchars($row['start_date']); ?></td><td><?php echo $row['end_date']?htmlspecialchars($row['end_date']):'Not set'; ?></td><td><span class="badge badge-<?php echo strtolower($row['status']); ?>"><?php echo htmlspecialchars($row['status']); ?></span></td><td><div class="btn-group"><a class="btn btn-sm btn-secondary" href="<?php echo $basePath; ?>/pages/edit_contract.php?id=<?php echo $row['contract_id']; ?>">Edit</a><a class="btn btn-sm btn-danger" href="<?php echo $basePath; ?>/pages/delete_contract.php?id=<?php echo $row['contract_id']; ?>" onclick="return confirm('Are you sure you want to delete this contract?');">Delete</a></div></td></tr><?php endwhile; else:?><tr><td colspan="9"><div class="empty-state"><p>No contracts found.</p><a class="btn" href="<?php echo $basePath; ?>/pages/add_contract.php">Add the first contract</a></div></td></tr><?php endif;?></tbody></table></div></section><?php include __DIR__ . '/../includes/footer.php'; $conn->close(); ?>